#!/usr/bin/env bash
# Check that every tracked Lean file starts with the Apache 2.0 copyright header.
# The import lists generated by scripts/update-imports.sh are exempt.
set -euo pipefail
cd "$(dirname "$0")/.."

missing=0
while IFS= read -r file; do
  case "$file" in
    MathEconLib.lean|MathEconLibTest.lean) continue ;;
  esac
  header=$(head -n 7 "$file")
  if [[ "$(sed -n 1p <<< "$header")" != "/-" ]] \
    || ! grep -qE '^Copyright \(c\) [0-9]{4} ' <<< "$header" \
    || ! grep -qF 'All rights reserved.' <<< "$header" \
    || ! grep -qxF 'Released under Apache 2.0 license as described in the file LICENSE.' <<< "$header" \
    || ! grep -qE '^Authors: .+' <<< "$header"; then
    echo "::error file=$file::missing or malformed copyright header"
    missing=$((missing + 1))
  fi
done < <(git ls-files '*.lean')

if (( missing > 0 )); then
  echo "$missing Lean file(s) lack the copyright header. See CONTRIBUTING.md."
  exit 1
fi
echo "All Lean files carry the copyright header."
